    function run(string memory n, string memory s) public {
        require(bytes(n).length > 0);

        PayoffDefinition memory pd;
        JumpRateUtilizationCurve memory curve;
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: n,
            symbol: s,
            payoffDefinition: pd,
            oracle: IOracleProvider(address(c)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: curve
        });

        bool revertedInit;
        try c.initialize(info) { revertedInit = false; } catch { revertedInit = true; }

        bool nameKept = keccak256(bytes(c.name())) == keccak256(bytes(n));
        bool symbolKept = keccak256(bytes(c.symbol())) == keccak256(bytes(s));

        bool revertedSecond;
        try c.initialize(info) { revertedSecond = false; } catch { revertedSecond = true; }

        assert(revertedInit || (nameKept && symbolKept && revertedSecond));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 newMaintenance) public {
        require(newMaintenance <= 1e24);

        bool reverted;
        try c.updateMaintenance(UFixed18.wrap(newMaintenance)) { reverted = false; } catch { reverted = true; }

        // On a fresh product the coordinator mapping is empty, so owner() is the zero
        // address and no caller can satisfy the onlyProductOwner check; the update
        // must revert and the maintenance parameter must remain zero.
        assert(reverted && UFixed18.unwrap(c.maintenance()) == 0);
    }

    receive() external payable {}
}

