contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 makerSmall, uint256 makerLarge, uint256 taker) public view {
        require(makerSmall > 0 && makerSmall <= makerLarge, "maker order");
        require(taker <= makerSmall, "taker bound");
        require(makerLarge <= type(uint256).max / 1e18, "maker overflow");
        require(taker <= type(uint256).max / 1e18, "taker overflow");

        Position memory p1 = Position({ maker: UFixed18.wrap(makerSmall), taker: UFixed18.wrap(taker) });
        Position memory p2 = Position({ maker: UFixed18.wrap(makerLarge), taker: UFixed18.wrap(taker) });

        int256 r1 = Fixed18.unwrap(c.rate(p1));
        int256 r2 = Fixed18.unwrap(c.rate(p2));

        assert(r1 >= r2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string memory name_,
        string memory symbol_,
        uint256 maintenanceRaw,
        uint256 fundingFeeRaw,
        uint256 makerFeeRaw
    ) public {
        // fees must be valid (<= 1 unit of 1e18) for initialization to succeed
        require(fundingFeeRaw <= 1e18 && makerFeeRaw <= 1e18);

        PayoffDefinition memory pd = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.wrap(0),
            payoffDirection: PayoffDefinitionLib.PayoffDirection.wrap(0),
            data: bytes30(0)
        });

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name_,
            symbol: symbol_,
            payoffDefinition: pd,
            oracle: IOracleProvider(address(c)),
            maintenance: UFixed18.wrap(maintenanceRaw),
            fundingFee: UFixed18.wrap(fundingFeeRaw),
            makerFee: UFixed18.wrap(makerFeeRaw),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(maintenanceRaw),
            utilizationCurve: curve
        });

        bool initOk;
        try c.initialize(info) {
            initOk = true;
        } catch {
            initOk = false;
        }

        bool secondReverted;
        if (initOk) {
            try c.initialize(info) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
        }

        // view reads of the public surface
        string memory nm = c.name();
        string memory sym = c.symbol();
        uint256 ff = UFixed18.unwrap(c.fundingFee());
        uint256 mf = UFixed18.unwrap(c.makerFee());
        uint256 mant = UFixed18.unwrap(c.maintenance());

        assert(
            !initOk || (
                keccak256(bytes(nm)) == keccak256(bytes(name_)) &&
                keccak256(bytes(sym)) == keccak256(bytes(symbol_)) &&
                ff == fundingFeeRaw &&
                mf == makerFeeRaw &&
                mant == maintenanceRaw &&
                secondReverted
            )
        );
    }

    receive() external payable {}
}

