contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public {
        // Fresh product: initial observable state
        bool closedBefore = c.closed();
        uint256 versionBefore = c.latestVersion();

        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }

        bool settleAccountReverted;
        try c.settleAccount(address(this)) { settleAccountReverted = false; } catch { settleAccountReverted = true; }

        bool updateClosedReverted;
        try c.updateClosed(true) { updateClosedReverted = false; } catch { updateClosedReverted = true; }

        bool closedAfter = c.closed();
        uint256 versionAfter = c.latestVersion();

        assert(
            closedBefore == false &&
            versionBefore == 0 &&
            settleReverted &&
            settleAccountReverted &&
            updateClosedReverted &&
            closedAfter == false &&
            versionAfter == 0
        );
    }
    receive() external payable {}
}

